    /// Returns (lt, eq) for a comparison between lhs and rhs at `rotation`.
    pub fn expr(
        &self,
        meta: &mut VirtualCells<F>,
        rotation: Option<Rotation>,
    ) -> (Expression<F>, Expression<F>) {
        (
            // lt already honors the requested rotation.
            self.lt_chip.config.is_lt(meta, rotation),
            // eq MUST be evaluated at the SAME rotation, not a cached
            // Rotation::cur() expression, otherwise lt and eq refer to
            // different rows.
            self.eq_chip.config.expr_at(meta, rotation),
        )
    }
}

impl<F: Field> IsEqualConfig<F> {
    /// Recompute the is_equal expression at an arbitrary rotation.
    pub fn expr_at(
        &self,
        meta: &mut VirtualCells<F>,
        rotation: Option<Rotation>,
    ) -> Expression<F> {
        let rot = rotation.unwrap_or_else(Rotation::cur);
        self.is_zero.expr_at(meta, rot)
    }
