    builder: &mut Builder<C>,
    config: &FriConfigVariable<C>,
    commit_phase_commits: &Array<C, DigestVariable<C>>,
    index_bits: &Array<C, Var<C::N>>,
    proof: &FriQueryProofVariable<C>,
    betas: &Array<C, Ext<C::F, C::EF>>,
    betas_squared: &Array<C, Ext<C::F, C::EF>>, // precomputed beta^2 cache
    reduced_openings: &Array<C, Ext<C::F, C::EF>>,
    log_max_lde_height: RVar<C::N>,
) -> Ext<C::F, C::EF> {
    // Enforce the final polynomial degree: its length must match the config.
    builder.assert_usize_eq(proof.final_poly.len(), config.final_poly_len());

    let folded_eval: Ext<C::F, C::EF> = builder.eval(C::F::ZERO);
    // ... set up x, two_adic_generator ...

    builder.assert_usize_eq(proof.commit_phase_openings.len(), commit_phase_commits.len());
    builder.range(0, commit_phase_commits.len()).for_each(|i_vec, builder| {
        let i = i_vec[0];
        let log_folded_height_plus_one = /* ... */ ;
        let beta = builder.get(betas, i);
        let beta_squared = builder.get(betas_squared, i);

