		c.api.AssertIsLessOrEqual(result[i], maxBabyBear)
	}
	out := ExtensionVariable{Value: [4]Variable{xinv, yinv, zinv, linv}}
	product := c.MulE(in, out)
	c.AssertIsEqualE(product, NewE([]string{"1", "0", "0", "0"}))
	return out
}
